// ============================================================
// stockTypes.ts
// スターホース3「株券」データの型定義。
// 種牡馬・繁殖牝馬(HorseRecord)とは別に存在する、株券アイテムのカタログ。
// 1頭の馬名につき、レアリティ違いの株券カードが複数存在する。
// ============================================================

/** 株券1枚の入手条件・交換条件 */
export interface StockCondition {
  /** "出現条件" / "交換条件" など */
  label: string;
  text: string;
}

/** 株券1枚（レアリティ単位）の情報 */
export interface StockCard {
  /** "★" / "★★" / "★★★" / "RARE" */
  rarity: string;
  /** レアリティごとのCSSクラス相当の識別子（元サイトの表記をそのまま保持） */
  rarity_class: string;
  /** 必要ポイント数（sh） */
  sh: number;
  sh_text: string;
  /** セレブ名（付与されている場合のみ。無ければ null） */
  celeb: string | null;
  /** 元サイトの画像パス（今回のページでは未使用） */
  image: string;
  conditions: StockCondition[];
}

/** 株券1銘柄（馬名単位）のレコード */
export interface StockRecord {
  name: string;
  horse_type: "sire" | "mare";
  cards: StockCard[];
}

/** レアリティの表示順（値が小さいほど先に表示） */
export const RARITY_ORDER: Record<string, number> = {
  "★": 1,
  "★★": 2,
  "★★★": 3,
  "RARE": 4,
};

export function rarityRank(rarity: string): number {
  return RARITY_ORDER[rarity] ?? 99;
}

/** レアリティごとの表示色（バッジ用） */
export const RARITY_COLOR: Record<string, string> = {
  "★": "#9e9e9e",
  "★★": "#42a5f5",
  "★★★": "#ffb300",
  "RARE": "#d32f2f",
};

export const RARITY_TEXT_COLOR: Record<string, string> = {
  "★": "#ffffff",
  "★★": "#ffffff",
  "★★★": "#ffffff",
  "RARE": "#ffffff",
};

export const ALL_RARITIES = ["★", "★★", "★★★", "RARE"];
