export const HORSE_NAME_ALIAS_MAP: Record<string, string> = {};
for (const group of HORSE_NAME_ALIAS_GROUPS) {
  HORSE_NAME_ALIAS_MAP[group.canonical] = group.canonical;
  for (const alias of group.aliases) {
    HORSE_NAME_ALIAS_MAP[alias] = group.canonical;
  }
}

/**
 * 祖先名を同一個体判定用の正規名（カタログ本体での日本語表記）に変換する。
 * 表記ゆれが登録されていない名前はそのまま返す。
 */
export function canonicalizeHorseName(name: string): string {
  const fromAlias = HORSE_NAME_ALIAS_MAP[name];
  if (fromAlias) return fromAlias;
  const effectRow = INBREED_EFFECT_MAP[name];
  if (effectRow) return effectRow.name;
  return name;
}
