// src/farm/harvestUtils.ts
// 収穫内容（例: "水コメ スイカ*5"）を品目ごとに分解・集計するためのユーティリティ。

import { HarvestRecord } from './farmApi';

export interface HarvestItem {
  名称: string;
  個数: number;
}

export interface ItemTotal extends HarvestItem {
  /** その品目が登場した収穫回数。 */
  回数: number;
}

// 品目の区切り（空白・全角空白・読点・カンマ・中黒・スラッシュ）
const SEPARATOR = /[\s、,，・/]+/;
// "スイカ*5" "スイカ×5" のように記号で個数を書いたもの
const QUANTITY_WITH_MARK = /^(.+?)\s*[*×xX＊]\s*(\d+)\s*(?:個|コ)?$/;
// "スイカ5個" のように「個/コ」で個数を書いたもの（名前に数字を含む品目を誤検出しないよう単位必須）
const QUANTITY_WITH_UNIT = /^(.+?)\s*(\d+)\s*(?:個|コ)$/;
// "5個" のように個数だけが独立したトークン。直前の品目の個数として扱う。
const QUANTITY_ONLY = /^(\d+)\s*(?:個|コ)?$/;

/** 1行分の収穫内容を品目と個数に分解する。個数の記載がなければ1として扱う。 */
export function parseHarvestContent(content: string): HarvestItem[] {
  if (!content) return [];

  const items: HarvestItem[] = [];

  content
    .split(SEPARATOR)
    .map((token) => token.trim())
    .filter((token) => token.length > 0)
    .forEach((token) => {
      const marked = QUANTITY_WITH_MARK.exec(token) || QUANTITY_WITH_UNIT.exec(token);
      if (marked) {
        items.push({ 名称: marked[1].trim(), 個数: Number(marked[2]) });
        return;
      }

      const onlyQuantity = QUANTITY_ONLY.exec(token);
      if (onlyQuantity && items.length > 0) {
        items[items.length - 1].個数 = Number(onlyQuantity[1]);
        return;
      }

      items.push({ 名称: token, 個数: 1 });
    });

  return items;
}

/** 収穫履歴をまたいで品目ごとの合計個数を出す。個数の多い順に並べる。 */
export function summarizeItems(records: HarvestRecord[]): ItemTotal[] {
  const totals = new Map<string, ItemTotal>();

  records.forEach((record) => {
    parseHarvestContent(record.収穫内容).forEach((item) => {
      const current = totals.get(item.名称);
      if (current) {
        current.個数 += item.個数;
        current.回数 += 1;
      } else {
        totals.set(item.名称, { 名称: item.名称, 個数: item.個数, 回数: 1 });
      }
    });
  });

  return Array.from(totals.values()).sort(
    (a, b) => b.個数 - a.個数 || a.名称.localeCompare(b.名称, 'ja')
  );
}

// ------------------------------------------------------------
// 収穫内容の分類（コメント / カウンタ）
//
// harvest_content には評価コメント（最高級・すばらしい等）は含まれておらず、
// "水コメ ドリアン*1" のようにカテゴリ名+品目のみが入っている。
// ただしこのゲームの収穫結果は各カテゴリごとに完全に決まった組み合わせしか
// 出ないため、実績として観測された文字列と評価ランクの対応表を持てば
// 「収穫内容の文字列 → 評価コメント」を一意に逆引きできる。
// ------------------------------------------------------------

/** 評価ランク（上記以外＝カテゴリ内で他の4パターンに一致しない場合） */
type HarvestRank = '最高級' | 'すばらしい' | 'とても良い' | 'まあまあ';

/** 画面に出す「コメント」表記 */
export type HarvestComment = '超成功' | '大成功' | '成功' | '普通' | '失敗' | 'その他';

const RANK_TO_COMMENT: Record<HarvestRank, HarvestComment> = {
  最高級: '超成功',
  すばらしい: '大成功',
  とても良い: '成功',
  まあまあ: '普通',
};

interface HarvestCategoryDef {
  /** 収穫内容の先頭に付くカテゴリ名（例: "水コメ"） */
  category: string;
  /** 集計用カウンタ名 */
  counterKey: string;
  /** 評価ランクごとに完全一致する収穫内容の実績値 */
  exact: Partial<Record<HarvestRank, string>>;
}

