export interface HarvestClassification {
  comment: HarvestComment;
  /** 水コメ/肥料水コメ/肥料雑草コメ/雑草コメ/虫コメ/千両箱/その他 */
  category: string;
  /** 集計用カウンタ名。集計対象外（その他）の場合は null。 */
  counterKey: string | null;
}

// Bootstrap の bg-* クラスは !important 付きのため、Badge に inline style で
// 直接色（hex）を当てても上書きされて表示に反映されない。
// そのため Badge には bg プロパティ（Bootstrapのバリアント名）を使い、
// グラフ（recharts の SVG fill）には hex 値を使う、という2種類を用意する。
// 見た目の色自体は両方とも揃えてある。

/** カテゴリごとのバッジ色（Bootstrapバリアント名）。 */
