/**
 * 収穫内容の文字列から、表示用にカテゴリ名の重複部分を取り除いた「品目部分」を返す。
 * 例: "水コメ メロン*4" + category="水コメ" → "メロン*4"
 * カテゴリ名を含まない/一致しない場合はそのまま返す。
 */
export function harvestItemDetail(content: string, category: string): string {
  const trimmed = (content || '').trim();
  if (category !== 'その他' && trimmed.startsWith(category)) {
    return trimmed.slice(category.length).trim();
  }
  return trimmed;
}

/** "YYYY-MM-DD HH:MM:SS" → "YYYY-MM-DD HH:MM"（秒を切り捨てる）。 */
export function formatHarvestDateTime(raw: string): string {
  if (!raw) return raw;
  const match = raw.match(/^(\d{4}-\d{2}-\d{2} \d{2}:\d{2})/);
  return match ? match[1] : raw;
}

/** 収穫内容の文字列を「コメント」「カテゴリ」「カウンタ」に分類する。 */
export function classifyHarvestContent(content: string): HarvestClassification {
  const trimmed = (content || '').trim();

  if (trimmed === '千両箱') {
    return { comment: 'その他', category: '千両箱', counterKey: '千両箱Count' };
  }

  const def = HARVEST_CATEGORIES.find((d) => trimmed.startsWith(d.category));
  if (!def) {
    return { comment: 'その他', category: 'その他', counterKey: null };
  }

  const matchedRank = (Object.keys(def.exact) as HarvestRank[]).find(
    (rank) => def.exact[rank] === trimmed
  );
  const comment = matchedRank ? RANK_TO_COMMENT[matchedRank] : '失敗';

  return { comment, category: def.category, counterKey: def.counterKey };
}

/** カウンタ名ごとの件数。表示順は水コメ→肥料水コメ→肥料雑草コメ→雑草コメ→虫コメ→千両箱。 */
export function summarizeCounters(records: HarvestRecord[]): { counterKey: string; 件数: number }[] {
  const counts = new Map<string, number>();

  records.forEach((record) => {
    const { counterKey } = classifyHarvestContent(record.収穫内容);
    if (!counterKey) return;
    counts.set(counterKey, (counts.get(counterKey) || 0) + 1);
  });

  const order = [
    '水コメCount', '肥料水コメCount', '肥料雑草コメCount', '雑草コメCount', '虫コメCount', '千両箱Count',
  ];
  return order
    .filter((key) => counts.has(key))
    .map((counterKey) => ({ counterKey, 件数: counts.get(counterKey)! }));
}

// ------------------------------------------------------------
// ペイアウト率（カテゴリごとの点数を割り当てて平均する）
// その他は点数が定義できないため、合計にも件数にも含めない。
// ------------------------------------------------------------
const PAYOUT_WEIGHT: Record<string, number> = {
  千両箱: 1000,
  肥料水コメ: 1000,
  肥料雑草コメ: 400,
  水コメ: 200,
  雑草コメ: 100,
  虫コメ: 40,
};

export interface PayoutRateResult {
  /** その他を除いた対象件数1回あたりの平均ポイント。対象0件なら0。 */
  rate: number;
  /** 対象件数の合計ポイント。 */
  totalPoints: number;
  /** 点数計算の対象になった件数（その他を除く）。 */
  countedRecords: number;
  /** その他として点数計算から除外した件数。 */
  excludedOther: number;
}

/** records（呼び出し側で件数を絞り込んだもの）からペイアウト率を計算する。 */
export function computePayoutRate(records: HarvestRecord[]): PayoutRateResult {
  let totalPoints = 0;
  let countedRecords = 0;
  let excludedOther = 0;

  records.forEach((record) => {
    const { category } = classifyHarvestContent(record.収穫内容);
    const weight = PAYOUT_WEIGHT[category];
    if (weight === undefined) {
      excludedOther += 1;
      return;
    }
    totalPoints += weight;
    countedRecords += 1;
  });

  return {
    rate: countedRecords > 0 ? totalPoints / countedRecords : 0,
    totalPoints,
    countedRecords,
    excludedOther,
  };
}

/** 厩舎ごとの収穫回数。だれが何回収穫したかの確認用。 */
export function summarizeStables(records: HarvestRecord[]): { 厩舎名: string; 回数: number }[] {
  const counts = new Map<string, number>();

  records.forEach((record) => {
    const name = record.厩舎名 || '(厩舎名なし)';
    counts.set(name, (counts.get(name) || 0) + 1);
  });

  return Array.from(counts.entries())
    .map(([厩舎名, 回数]) => ({ 厩舎名, 回数 }))
    .sort((a, b) => b.回数 - a.回数 || a.厩舎名.localeCompare(b.厩舎名, 'ja'));
}
