import React, { useState, useMemo } from "react";
import { Container, Form, Button, Row, Col, Card, Table, ToggleButton, ToggleButtonGroup } from 'react-bootstrap';
import { HorseIDData, BloodData } from './TaneData';
import { useNavigate } from "react-router-dom";

const Blood: React.FC = () => {
    const navigate = useNavigate();
    const [bloodDataList] = useState(BloodData);
    const [filteredHorseList, setFilteredHorseList] = useState(BloodData);
    const [checkFlg, setCheckFlg] = useState<boolean>(false); 
    const [selectedHorseId, setSelectedHorseId] = useState<string>("B09");
    const [category, setCategory] = useState<"stallion" | "mare">("mare");

    const [filterKetto, setFilterKetto] = useState<string>("all");
    const [filterAisyo, setFilterAisyo] = useState<string>("all");

    type bdData = {
        kettoId: string; kettoName: string; name: string;
        memo1: string; memo2: string; memo3: string;
    };
    const [sortConfig, setSortConfig] = useState<{ key: keyof bdData; direction: "asc" | "desc" } | null>(null);

    const finalDisplayData = useMemo(() => {
        let result = filteredHorseList.filter(item => {
            const matchKetto = filterKetto === "all" || item.kettoName === filterKetto;
            const matchAisyo = filterAisyo === "all" || item.memo1 === filterAisyo;
            return matchKetto && matchAisyo;
        });

        if (sortConfig) {
            result.sort((a, b) => {
                const aValue = a[sortConfig.key] || "";
                const bValue = b[sortConfig.key] || "";
                const order = sortConfig.direction === "asc" ? 1 : -1;
                return aValue.localeCompare(bValue, 'ja') * order;
            });
        }
        return result;
    }, [filteredHorseList, filterKetto, filterAisyo, sortConfig]);

    const kettoOptions = useMemo(() => ["all", ...Array.from(new Set(filteredHorseList.map(i => i.kettoName)))], [filteredHorseList]);
    const aisyoOptions = useMemo(() => ["all", ...Array.from(new Set(filteredHorseList.map(i => i.memo1)))], [filteredHorseList]);

    const handleSort = (key: keyof bdData) => {
        setSortConfig((prev) => {
            if (prev && prev.key === key) {
                return { key, direction: prev.direction === "asc" ? "desc" : "asc" };
            }
            return { key, direction: "asc" };
        });
    };

    const handleCategoryChange = (val: "stallion" | "mare") => {
        setCategory(val);
        setSelectedHorseId(val === "mare" ? "B09" : "A22");
    };

    const [checkedItems, setCheckedItems] = useState<{ [key: string]: boolean }>({ "堅実": true, "平均": false, "一発": false });
    const [checkedItems_2, setCheckedItems_2] = useState<{ [key: string]: boolean }>({ "無限株券": false });

    const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
        event.preventDefault();
        if (!checkedItems["堅実"] && !checkedItems["平均"] && !checkedItems["一発"]) {
            alert('1つ以上チェックしてください！');
            return;
        }
        setCheckFlg(true);
        setFilterKetto("all");
        setFilterAisyo("all");

        const bdList = bloodDataList.filter(a => category === "stallion" ? a.kettoId.startsWith("B") : a.kettoId.startsWith("A"))
        const horseData1 = HorseIDData.find(a => a.horseID === selectedHorseId);
        const selectData = horseData1 ? horseData1.aisyo.split('') : [];

        const tete = bdList.map((i) => {
            const tempItem = { ...i }; 
            const getHaigoId = Number(tempItem.kettoId.replace("A", "").replace("B", ""));
            const haigoPln = selectData[getHaigoId - 1];

            if(checkedItems_2["無限株券"] && tempItem.memo2 !== "無限株券") return null;

            if ((haigoPln === "1" && checkedItems["堅実"]) ||
                (haigoPln === "2" && checkedItems["平均"]) ||
                (haigoPln === "3" && checkedItems["一発"])) {
                
                if (haigoPln === '1') tempItem.memo1 = '堅実';
                if (haigoPln === '2') tempItem.memo1 = '平均';
                if (haigoPln === '3') tempItem.memo1 = '一発';

                horseData1?.memo1.split(",").forEach((i_str) => {
                    if (i_str === tempItem.kettoId) tempItem.memo1 = "鉄板";
                });
                return tempItem;
            }
            return null;
        }).filter((i): i is bdData => i !== null);
        
        setFilteredHorseList(tete);
    }

    const filteredDataA = HorseIDData.filter(a => category === "stallion" ? a.horseID.startsWith("A") : a.horseID.startsWith("B")).sort((a, b) => a.horseKeitou.localeCompare(b.horseKeitou));

    return (
        <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh', paddingBottom: '50px' }}>
            <Container className="pt-4" style={{ maxWidth: '750px' }}>
                <Card className="shadow border-0 mb-4" style={{ borderRadius: '16px' }}>
                    <div style={{ height: '6px', backgroundColor: '#0d6efd' }}></div>
                    <Card.Body className="p-4">
                        <h4 className="text-center mb-4" style={{ fontWeight: '800' }}>BLOOD CHECK<span style={{ color: '#0d6efd', fontSize: '0.8em', fontWeight: 'bold' }}> | 配合相手チェック</span></h4>
                        <Form onSubmit={handleSubmit}>
                            <Row className="mb-3">
                                <Col xs={12} md={5}>
                                    <Form.Label className="small fw-bold text-muted">性別</Form.Label>
                                    <div className="d-flex mb-3">
                                        <ToggleButtonGroup type="radio" name="category" defaultValue={category} className="w-100 shadow-sm">
                                            <ToggleButton 
                                                id="tgl-stallion" 
                                                value="stallion" 
                                                variant={category === "stallion" ? "dark" : "outline-dark"}
                                                onChange={() => handleCategoryChange("stallion")}
                                                className="fw-bold"
                                            >
                                                種牡馬
                                            </ToggleButton>
                                            <ToggleButton 
                                                id="tgl-mare" 
                                                value="mare" 
                                                variant={category === "mare" ? "dark" : "outline-dark"}
                                                onChange={() => handleCategoryChange("mare")}
                                                className="fw-bold"
                                            >
                                                繁殖牝馬
                                            </ToggleButton>
                                        </ToggleButtonGroup>
                                    </div>
                                </Col>
                                <Col xs={12} md={7}>
                                    <Form.Label className="small fw-bold text-muted">配合元の系統</Form.Label>
                                    <Form.Select value={selectedHorseId} onChange={(e) => setSelectedHorseId(e.target.value)} className="shadow-sm">
                                        {filteredDataA.map((item) => (
                                            <option key={item.horseID} value={item.horseID}>{item.horseKeitou}</option>
                                        ))}
                                    </Form.Select>
                                </Col>
                            </Row>
                            <Row className="mb-4">
                                <Col xs={12} md={8}>
                                    <Form.Label className="small fw-bold text-muted">相性（複数選択可）</Form.Label>
                                    <div className="d-flex gap-2">
                                        {[
                                            { label: "堅実", variant: "primary" },
                                            { label: "平均", variant: "warning" },
                                            { label: "一発", variant: "danger" }
                                        ].map((item) => (
                                            <ToggleButton
                                                key={item.label}
                                                id={`tgl-${item.label}`}
                                                type="checkbox"
                                                variant={checkedItems[item.label] ? item.variant : `outline-${item.variant}`}
                                                value={item.label}
                                                checked={checkedItems[item.label]}
                                                onChange={(e) => setCheckedItems({...checkedItems, [item.label]: e.currentTarget.checked})}
                                                className="flex-fill fw-bold shadow-sm"
                                                size="sm"
                                                style={{ color: (checkedItems[item.label] && item.label === "平均") ? "#333" : "" }}
                                            >
                                                {item.label}
                                            </ToggleButton>
                                        ))}
                                    </div>
                                </Col>
                                <Col xs={12} md={4}>
                                    <Form.Label className="small fw-bold text-muted">オプション</Form.Label>
                                    <ToggleButton
                                        id="tgl-mugen"
                                        type="checkbox"
                                        variant={checkedItems_2["無限株券"] ? "success" : "outline-success"}
                                        value="1"
                                        checked={checkedItems_2["無限株券"]}
                                        onChange={(e) => setCheckedItems_2({...checkedItems_2, "無限株券": e.currentTarget.checked})}
                                        className="w-100 fw-bold shadow-sm"
                                        size="sm"
                                    >
                                        無限株券のみ
                                    </ToggleButton>
                                </Col>
                            </Row>
                            <Button type="submit" className="w-100 fw-bold py-2 shadow" style={{ background: 'linear-gradient(45deg, #0d6efd, #0a58ca)', border: 'none' }}>検索！</Button>
                        </Form>
                    </Card.Body>
                </Card>

                {checkFlg && (
                    <>
                        <Card className="mb-3 border-0 shadow-sm" style={{ backgroundColor: '#e9ecef' }}>
                            <Card.Body className="py-2 text-center">
                                <Row className="g-2">
                                    <Col xs={6}>
                                        <Form.Label className="small fw-bold mb-1">系統絞込</Form.Label>
                                        <Form.Select size="sm" value={filterKetto} onChange={(e) => setFilterKetto(e.target.value)}>
                                            <option value="all">すべて ({kettoOptions.length - 1})</option>
                                            {kettoOptions.filter(k => k !== "all").map(k => <option key={k} value={k}>{k}</option>)}
                                        </Form.Select>
                                    </Col>
                                    <Col xs={6}>
                                        <Form.Label className="small fw-bold mb-1">相性絞込</Form.Label>
                                        <Form.Select size="sm" value={filterAisyo} onChange={(e) => setFilterAisyo(e.target.value)}>
                                            <option value="all">すべて</option>
                                            {aisyoOptions.filter(a => a !== "all").map(a => <option key={a} value={a}>{a}</option>)}
                                        </Form.Select>
                                    </Col>
                                </Row>
                                <div className="mt-2 small text-muted fw-bold">該当件数: {finalDisplayData.length} 頭</div>
                            </Card.Body>
                        </Card>

                        <div className="shadow-sm mb-4" style={{ borderRadius: '12px', overflow: 'hidden', maxHeight: '600px', overflowY: 'auto' }}>
                            <Table className="table-bordered mb-0" style={{ fontSize: "14px", border: 'none' }}>
                                <thead className="text-center sticky-top" style={{ zIndex: 1 }}>
                                    <tr>
                                        <th onClick={() => handleSort("kettoName")} style={{ backgroundColor: '#0d6efd', color: '#ffffff', cursor: "pointer", padding: '12px', border: 'none', fontWeight: 'bold' }}>
                                            系統 {sortConfig?.key === "kettoName" ? (sortConfig.direction === "asc" ? "▲" : "▼") : ""}
                                        </th>
                                        <th onClick={() => handleSort("name")} style={{ backgroundColor: '#0d6efd', color: '#ffffff', cursor: "pointer", padding: '12px', border: 'none', fontWeight: 'bold' }}>
                                            馬名 {sortConfig?.key === "name" ? (sortConfig.direction === "asc" ? "▲" : "▼") : ""}
                                        </th>
                                        <th onClick={() => handleSort("memo1")} style={{ backgroundColor: '#0d6efd', color: '#ffffff', cursor: "pointer", padding: '12px', border: 'none', fontWeight: 'bold' }}>
                                            相性 {sortConfig?.key === "memo1" ? (sortConfig.direction === "asc" ? "▲" : "▼") : ""}
                                        </th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {finalDisplayData.map((data, index) => (
                                        <tr key={index} className="text-center align-middle">
                                            <td style={{ backgroundColor: '#3b3b3b', color: '#fff', borderColor: '#4a4a4a' }}>{data.kettoName}</td>
                                            <td style={{ backgroundColor: '#3b3b3b', color: '#fff', borderColor: '#4a4a4a' }}>{data.name}</td>
                                            <td style={{
                                                backgroundColor:
                                                    data.memo1 === '堅実' ? '#add6ff' : 
                                                    data.memo1 === '平均' ? '#ffff9e' : 
                                                    data.memo1 === '一発' ? '#ff9e9e' : 
                                                    data.memo1 === '鉄板' ? '#0080ff' : 
                                                    data.memo1 === '爆発' ? '#ff3333' : '#ffffff',
                                                color: (data.memo1 === '鉄板' || data.memo1 === '爆発') ? '#ffffff' : '#333',
                                                fontWeight: 'bold',
                                                borderColor: '#4a4a4a'
                                            }}>{data.memo1}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </Table>
                        </div>
                    </>
                )}

                <Button variant="success" className="w-100 fw-bold py-2" onClick={() => navigate("/")}>戻る</Button> 
            </Container>
        </div>
    );
};

export default Blood;