import React, { useState } from 'react';
import { useNavigate } from "react-router-dom";
import { Container, Form, Button, Row, Col, Card, Table, Collapse, InputGroup } from 'react-bootstrap';

const RACE_TEMPLATES = [
  { name: "SWBC", p1: 5000, p2: 1000, p3: 250 },
  { name: "WBC", p1: 2000, p2: 400, p3: 100 },
  { name: "G1(1500枚)", p1: 1500, p2: 350, p3: 80 },
  { name: "G1(1000枚)", p1: 1000, p2: 250, p3: 50 },
  { name: "G1(700枚)", p1: 700, p2: 160, p3: 30 },
  { name: "G1(500枚)", p1: 500, p2: 150, p3: 30 },
  { name: "G1(400枚)", p1: 400, p2: 120, p3: 30 },
  { name: "G2(200枚)", p1: 200, p2: 60, p3: 20 },
  { name: "G3(100枚)", p1: 100, p2: 30, p3: 10 },
  { name: "OP(50枚)", p1: 50, p2: 15, p3: 5 },
];

const Win: React.FC = () => {
  const navigate = useNavigate();

  const [oddsWin, setOddsWin] = useState<string>("");
  const [oddsPlace, setOddsPlace] = useState<string>("");
  const [sideAmount, setSideAmount] = useState<string>("");
  const [prize1, setPrize1] = useState<number>(2000);
  const [prize2, setPrize2] = useState<number>(400);
  const [prize3, setPrize3] = useState<number>(100);
  const [ridePO, setRidePO] = useState<string>("97.5");
  const [ownerPO, setOwnerPO] = useState<string>("82.0");

  const [showSettings, setShowSettings] = useState<boolean>(false);
  const [result, setResult] = useState<any>(null);

  const handleRaceChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const template = RACE_TEMPLATES.find(t => t.name === e.target.value);
    if (template) {
      setPrize1(template.p1);
      setPrize2(template.p2);
      setPrize3(template.p3);
    }
  };

  const calculate = (e: React.FormEvent) => {
    e.preventDefault();
    const oWin = parseFloat(oddsWin);
    const oPlace = parseFloat(oddsPlace);
    const side = parseFloat(sideAmount);
    const rPO = parseFloat(ridePO) / 100;
    const oPO = parseFloat(ownerPO) / 100;

    if (!oWin || !oPlace) return;

    const p1 = rPO / oWin;
    const p123 = rPO / oPlace;
    const targetEV = side * oPO;
    const p1Expected = p1 * prize1;
    const remainingP = p123 - p1;

    const p3 = (targetEV - p1Expected - (remainingP * prize2)) / (prize3 - prize2);
    const p2 = remainingP - p3;

    setResult({
      p1: p1 * 100,
      p2: p2 * 100,
      p3: p3 * 100,
      pOut: (1 - p123) * 100
    });
  };

  const backpage = () => { navigate("/"); };

  return (
    // 背景を元の薄いオレンジ(#fff5e6)に固定
    <div style={{ backgroundColor: '#fff5e6', minHeight: '100vh', paddingBottom: '50px' }}>
      <Container className="pt-5" style={{ maxWidth: '650px' }}>
        <Card className="shadow border-0 mb-4 rounded-4 overflow-hidden">
          {/* ヘッダーの色を元に戻す */}
          <Card.Header style={{ backgroundColor: '#ff944d', color: 'white' }} className="py-3">
            <h4 className="text-center mb-0 fw-bold">🐎 勝率計算機</h4>
          </Card.Header>
          
          <Card.Body className="p-4 bg-white">
            <Form onSubmit={calculate}>
              <Row className="g-4 mb-3">
                <Col xs={12}>
                  <Form.Label className="fw-bold" style={{ color: '#e67300' }}>🏆 レース選択</Form.Label>
                  <Form.Select 
                    size="lg" 
                    onChange={handleRaceChange} 
                    defaultValue="WBC" 
                    className="shadow-sm"
                    style={{ borderColor: '#ffcc99' }}
                  >
                    {RACE_TEMPLATES.map(t => (
                      <option key={t.name} value={t.name}>{t.name}</option>
                    ))}
                  </Form.Select>
                </Col>
                
                <Col xs={12} md={4}>
                  <Form.Label className="fw-bold text-secondary">単勝ライド</Form.Label>
                  <InputGroup>
                    <Form.Control type="number" step="0.001" value={oddsWin} onChange={(e) => setOddsWin(e.target.value)} placeholder="例: 2.345" />
                    <InputGroup.Text style={{ backgroundColor: '#fff0e6' }}>倍</InputGroup.Text>
                  </InputGroup>
                </Col>
                
                <Col xs={12} md={4}>
                  <Form.Label className="fw-bold text-secondary">複勝ライド</Form.Label>
                  <InputGroup>
                    <Form.Control type="number" step="0.001" value={oddsPlace} onChange={(e) => setOddsPlace(e.target.value)} placeholder="例: 2.345" />
                    <InputGroup.Text style={{ backgroundColor: '#fff0e6' }}>倍</InputGroup.Text>
                  </InputGroup>
                </Col>
                
                <Col xs={12} md={4}>
                  <Form.Label className="fw-bold text-secondary">サイド枚数</Form.Label>
                  <InputGroup>
                    <Form.Control type="number" value={sideAmount} onChange={(e) => setSideAmount(e.target.value)} placeholder="例: 100" />
                    <InputGroup.Text style={{ backgroundColor: '#fff0e6' }}>枚</InputGroup.Text>
                  </InputGroup>
                </Col>
              </Row>

              <div className="mt-4 border-top pt-3 text-center">
                <Button 
                  variant="link" 
                  size="sm" 
                  className="text-decoration-none" 
                  style={{ color: '#ff8533' }}
                  onClick={() => setShowSettings(!showSettings)}
                >
                  {showSettings ? "▲ 詳細設定を閉じる" : "▼ 賞金・PO率を個別設定する"}
                </Button>
                
                <Collapse in={showSettings}>
                  <div className="mt-3 p-4 rounded-3 border" style={{ backgroundColor: '#fffaf5' }}>
                    <Row className="g-3 mb-3">
                      <Col xs={4}>
                        <Form.Label size="sm" className="text-muted fw-bold small">1着賞金</Form.Label>
                        <InputGroup size="sm"><Form.Control type="number" value={prize1} onChange={(e) => setPrize1(Number(e.target.value))} /></InputGroup>
                      </Col>
                      <Col xs={4}>
                        <Form.Label size="sm" className="text-muted fw-bold small">2着賞金</Form.Label>
                        <InputGroup size="sm"><Form.Control type="number" value={prize2} onChange={(e) => setPrize2(Number(e.target.value))} /></InputGroup>
                      </Col>
                      <Col xs={4}>
                        <Form.Label size="sm" className="text-muted fw-bold small">3着賞金</Form.Label>
                        <InputGroup size="sm"><Form.Control type="number" value={prize3} onChange={(e) => setPrize3(Number(e.target.value))} /></InputGroup>
                      </Col>
                    </Row>
                    <Row className="g-3">
                      <Col xs={6}>
                        <Form.Label size="sm" className="text-muted fw-bold small">ライドPO率</Form.Label>
                        <InputGroup size="sm"><Form.Control type="number" value={ridePO} onChange={(e) => setRidePO(e.target.value)} /><InputGroup.Text>%</InputGroup.Text></InputGroup>
                      </Col>
                      <Col xs={6}>
                        <Form.Label size="sm" className="text-muted fw-bold small">馬主PO率</Form.Label>
                        <InputGroup size="sm"><Form.Control type="number" value={ownerPO} onChange={(e) => setOwnerPO(e.target.value)} /><InputGroup.Text>%</InputGroup.Text></InputGroup>
                      </Col>
                    </Row>
                  </div>
                </Collapse>
              </div>

              <Button 
                type="submit" 
                size="lg" 
                className="w-100 mt-4 py-3 fw-bold shadow-sm rounded-3 border-0"
                style={{ backgroundColor: '#ff8000', color: 'white' }}
              >
                🎯 計算を実行する
              </Button>
            </Form>
          </Card.Body>
        </Card>

        {result && (
          <Card className="shadow border-0 rounded-4 overflow-hidden mb-4">
            <Card.Header style={{ backgroundColor: '#4d2600', color: 'white' }} className="py-2 text-center">
              <h5 className="mb-0 fw-bold">📊 計算結果</h5>
            </Card.Header>
            <Table bordered hover className="mb-0 text-center align-middle" style={{ fontSize: '1.1rem' }}>
              <tbody>
                <tr style={{ backgroundColor: '#fff4cc' }}>
                  <td className="fw-bold w-50">🥇 1着率</td>
                  <td className="fw-bold text-end pe-4">{result.p1.toFixed(3)} <span className="fs-6">%</span></td>
                </tr>
                <tr style={{ backgroundColor: '#f2f2f2' }}>
                  <td className="fw-bold w-50">🥈 2着率</td>
                  <td className="fw-bold text-end pe-4">{result.p2.toFixed(3)} <span className="fs-6">%</span></td>
                </tr>
                <tr style={{ backgroundColor: '#ffe6e6' }}>
                  <td className="fw-bold w-50">🥉 3着率</td>
                  <td className="fw-bold text-end pe-4">{result.p3.toFixed(3)} <span className="fs-6">%</span></td>
                </tr>
                <tr className="bg-white">
                  <td className="fw-bold text-primary">連対率 (1~2着)</td>
                  <td className="text-end pe-4 text-primary fw-bold">{(result.p1 + result.p2).toFixed(3)} <span className="fs-6">%</span></td>
                </tr>
                {/* 3着内率を追加 */}
                <tr className="bg-white">
                  <td className="fw-bold text-danger">3着内率 (1~3着)</td>
                  <td className="text-end pe-4 text-danger fw-bold">{(result.p1 + result.p2 + result.p3).toFixed(3)} <span className="fs-6">%</span></td>
                </tr>
                <tr className="bg-white">
                  <td className="text-muted small">着外率 (4着以下)</td>
                  <td className="text-end pe-4 text-muted small">{result.pOut.toFixed(3)} <span className="fs-6">%</span></td>
                </tr>
              </tbody>
            </Table>
          </Card>
        )}

        <Button 
          variant="success" 
          className="w-100 fw-bold py-2 shadow-sm rounded-3" 
          onClick={backpage}
        >
          戻る
        </Button>
      </Container>
    </div>
  );
};

export default Win;