import React, { useEffect, useMemo, useState } from 'react';
import { Modal, Spinner, Table, Alert, Badge, Row, Col } from 'react-bootstrap';
import {
  BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, LabelList,
} from 'recharts';
import { HarvestRecord, fetchHarvestRecords } from './farmApi';
import {
  CATEGORY_BADGE_VARIANT, CATEGORY_COLOR_HEX, CATEGORY_ORDER, classifyHarvestContent,
  COMMENT_BADGE_VARIANT, COMMENT_COLOR_HEX, COMMENT_ORDER, computePayoutRate, formatHarvestDateTime,
  harvestItemDetail,
} from './harvestUtils';

/** ある分類（カテゴリ/コメント）の内訳を、指定した並び順の1行データ（100%積み上げ用）にする。 */
function buildBreakdown<T extends string>(
  records: HarvestRecord[],
  pick: (r: HarvestRecord) => T,
  order: readonly T[]
) {
  const counts = new Map<T, number>();
  records.forEach((r) => {
    const key = pick(r);
    counts.set(key, (counts.get(key) || 0) + 1);
  });
  const total = records.length;
  const presentOrder = order.filter((key) => counts.has(key));
  const row: Record<string, number | string> = { name: '構成比' };
  presentOrder.forEach((key) => {
    row[key] = total > 0 ? ((counts.get(key) || 0) / total) * 100 : 0;
  });
  return { row, order: presentOrder, counts, total };
}

/** ペイアウト率のパーセント換算基準（水コメの200点=100%とみなす）。 */
const PAYOUT_PERCENT_BASE = 200;

const RECENT_LIST_COUNT = 10;
const RECENT_STATS_COUNT = 100;

interface Props {
  stableName: string | null;
  onHide: () => void;
}

/**
 * 厩舎ごとの詳細ポップアップ。
 * 表示中の一覧（画面側のフィルタ）とは無関係に、その厩舎の直近データを
 * 都度APIから取得し直す（「過去10回/過去100回」は常に最新を指すため）。
 */
const StableDetailModal: React.FC<Props> = ({ stableName, onHide }) => {
  const [records, setRecords] = useState<HarvestRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!stableName) return;
    setLoading(true);
    setError(null);
    fetchHarvestRecords({ stable: stableName, order: 'desc', limit: RECENT_STATS_COUNT })
      .then(setRecords)
      .catch((err: any) => setError(err.message || '取得に失敗しました'))
      .finally(() => setLoading(false));
  }, [stableName]);

  const recent10 = useMemo(() => records.slice(0, RECENT_LIST_COUNT), [records]);

  const categoryBreakdown = useMemo(
    () => buildBreakdown(records, (r) => classifyHarvestContent(r.収穫内容).category, CATEGORY_ORDER),
    [records]
  );

  const commentBreakdown = useMemo(
    () => buildBreakdown(records, (r) => classifyHarvestContent(r.収穫内容).comment, COMMENT_ORDER),
    [records]
  );

  const payout = useMemo(() => computePayoutRate(records), [records]);

  return (
    <Modal show={stableName !== null} onHide={onHide} centered size="lg" scrollable>
      <Modal.Header closeButton>
        <Modal.Title style={{ fontSize: '1.05em' }}>{stableName} の詳細</Modal.Title>
      </Modal.Header>
      <Modal.Body>
        {error && <Alert variant="danger">{error}</Alert>}

        {loading ? (
          <div className="text-center py-5">
            <Spinner animation="border" />
          </div>
        ) : records.length === 0 ? (
          <div className="text-center text-muted py-4">収穫記録がありません</div>
        ) : (
          <>
            <h6 className="fw-bold mb-2">直近{RECENT_LIST_COUNT}回の収穫内容</h6>
            <Table size="sm" hover className="mb-4">
              <thead>
                <tr>
                  <th style={{ whiteSpace: 'nowrap' }}>収穫日時</th>
                  <th>収穫内容</th>
                  <th style={{ whiteSpace: 'nowrap' }}>コメント</th>
                </tr>
              </thead>
              <tbody>
                {recent10.map((r) => {
                  const { category, comment } = classifyHarvestContent(r.収穫内容);
                  const itemDetail = harvestItemDetail(r.収穫内容, category);
                  return (
                    <tr key={r.id}>
                      <td style={{ whiteSpace: 'nowrap' }}>{formatHarvestDateTime(r.収穫日時)}</td>
                      <td>
                        <Badge className="me-2" bg={CATEGORY_BADGE_VARIANT[category] || 'secondary'}>
                          {category}
                        </Badge>
                        {itemDetail && <span className="text-muted small">{itemDetail}</span>}
                      </td>
                      <td style={{ whiteSpace: 'nowrap' }}>
                        <Badge bg={COMMENT_BADGE_VARIANT[comment]}>{comment}</Badge>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </Table>

            <h6 className="fw-bold mb-2">
              直近{records.length}回の収穫内容・コメント分布
              {records.length < RECENT_STATS_COUNT && (
                <span className="text-muted fw-normal small ms-2">
                  （記録が{RECENT_STATS_COUNT}回未満のため全{records.length}回分）
                </span>
              )}
            </h6>
            <Row className="g-3 mb-4">
              <Col md={6}>
                <div className="small text-muted mb-1">収穫内容（カテゴリ）別</div>
                <div style={{ width: '100%', height: 60 }}>
                  <ResponsiveContainer>
                    <BarChart
                      data={[categoryBreakdown.row]}
                      layout="vertical"
                      margin={{ top: 0, right: 8, bottom: 0, left: 0 }}
                    >
                      <XAxis type="number" domain={[0, 100]} hide />
                      <YAxis type="category" dataKey="name" hide />
                      <Tooltip formatter={(value: any) => `${Number(value).toFixed(1)}%`} />
                      {categoryBreakdown.order.map((name) => (
                        <Bar key={name} dataKey={name} stackId="stack" fill={CATEGORY_COLOR_HEX[name] || '#6c757d'}>
                          <LabelList
                            dataKey={name}
                            position="center"
                            formatter={(v: any) => (Number(v) >= 6 ? `${Number(v).toFixed(0)}%` : '')}
                            style={{ fill: '#fff', fontSize: 11, fontWeight: 700 }}
                          />
                        </Bar>
                      ))}
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                <Table size="sm" className="mt-2 mb-0">
                  <tbody>
                    {categoryBreakdown.order.map((name) => (
                      <tr key={name}>
                        <td className="py-1">
                          <Badge bg={CATEGORY_BADGE_VARIANT[name] || 'secondary'}>{name}</Badge>
                        </td>
                        <td className="py-1 text-end">{categoryBreakdown.counts.get(name)}回</td>
                        <td className="py-1 text-end fw-bold" style={{ width: '4.5em' }}>
                          {((categoryBreakdown.counts.get(name)! / categoryBreakdown.total) * 100).toFixed(1)}%
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </Col>
              <Col md={6}>
                <div className="small text-muted mb-1">コメント別</div>
                <div style={{ width: '100%', height: 60 }}>
                  <ResponsiveContainer>
                    <BarChart
                      data={[commentBreakdown.row]}
                      layout="vertical"
                      margin={{ top: 0, right: 8, bottom: 0, left: 0 }}
                    >
                      <XAxis type="number" domain={[0, 100]} hide />
                      <YAxis type="category" dataKey="name" hide />
                      <Tooltip formatter={(value: any) => `${Number(value).toFixed(1)}%`} />
                      {commentBreakdown.order.map((name) => (
                        <Bar key={name} dataKey={name} stackId="stack" fill={COMMENT_COLOR_HEX[name] || '#6c757d'}>
                          <LabelList
                            dataKey={name}
                            position="center"
                            formatter={(v: any) => (Number(v) >= 6 ? `${Number(v).toFixed(0)}%` : '')}
                            style={{ fill: '#fff', fontSize: 11, fontWeight: 700 }}
                          />
                        </Bar>
                      ))}
                    </BarChart>
                  </ResponsiveContainer>
                </div>
                <Table size="sm" className="mt-2 mb-0">
                  <tbody>
                    {commentBreakdown.order.map((name) => (
                      <tr key={name}>
                        <td className="py-1">
                          <Badge bg={COMMENT_BADGE_VARIANT[name]}>{name}</Badge>
                        </td>
                        <td className="py-1 text-end">{commentBreakdown.counts.get(name)}回</td>
                        <td className="py-1 text-end fw-bold" style={{ width: '4.5em' }}>
                          {((commentBreakdown.counts.get(name)! / commentBreakdown.total) * 100).toFixed(1)}%
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </Col>
            </Row>

            <h6 className="fw-bold mb-2">
              直近{records.length}回のペイアウト率
            </h6>
            <div className="p-3 mb-2" style={{ backgroundColor: '#f8f9fa', borderRadius: '10px' }}>
              <span className="fw-bold" style={{ fontSize: '1.4em' }}>
                {((payout.rate / PAYOUT_PERCENT_BASE) * 100).toFixed(1)}%
              </span>
              <div className="text-muted small mt-1">
                対象{payout.countedRecords}回（その他{payout.excludedOther}回を除く）・合計{payout.totalPoints}点
              </div>
              <div className="text-muted small">
                千両箱1000 / 肥料水1000 / 肥料雑草400 / 水200 / 雑草100 / 虫40（その他は計算に含めない）
              </div>
            </div>
          </>
        )}
      </Modal.Body>
    </Modal>
  );
};

export default StableDetailModal;
