import React, { useState, useEffect, useMemo } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { Container, Form, Card, Table, Button, Accordion, Badge, Row, Col, Spinner, Alert } from 'react-bootstrap';
import { QrRecord, fetchQrRecords } from './qrApi';
import 'bootstrap/dist/css/bootstrap.min.css';

const QrRead: React.FC = () => {
  // ==========================================
  // 0. DBからのデータ取得
  // ==========================================
  const [qrList, setQrList] = useState<QrRecord[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    fetchQrRecords()
      .then(setQrList)
      .catch((e) => setLoadError(e.message || 'データの取得に失敗しました'))
      .finally(() => setLoading(false));
  }, []);

  // ==========================================
  // 1. データ集計・グループ化ロジック
  // ==========================================
  const dataSets = useMemo(() => {
    const groups: { [key: string]: QrRecord[] } = {};
    qrList.forEach((item) => {
      const category = item.分類?.trim() || '未分類';
      if (item.読み取りデータ?.trim()) {
        if (!groups[category]) groups[category] = [];
        groups[category].push(item);
      }
    });

    Object.keys(groups).forEach(key => {
      groups[key].sort((a, b) => {
        const nameA = a.QRファイル名 || '';
        const nameB = b.QRファイル名 || '';
        return nameA.localeCompare(nameB, undefined, { numeric: true });
      });
    });

    const sortedGroups: { [key: string]: QrRecord[] } = {};
    Object.keys(groups).sort().forEach(key => {
      sortedGroups[key] = groups[key];
    });

    return sortedGroups;
  }, [qrList]);

  const categories = Object.keys(dataSets);
  const [selectedListKey, setSelectedListKey] = useState<string>('');
  const [currentIndex, setCurrentIndex] = useState<number>(0);
  const [checkedItems, setCheckedItems] = useState<boolean[]>([]);
  
  const [isActive, setIsActive] = useState<boolean>(false);
  const [showImage, setShowImage] = useState<boolean>(true);

  // ==========================================
  // 🌟 2. 設定ステート（LocalStorageからの読み込み）
  // ==========================================
  // 保存・読み込み用の関数
  const getSavedValue = (key: string, defaultValue: any) => {
    const saved = localStorage.getItem(`qr_config_${key}`);
    return saved !== null ? JSON.parse(saved) : defaultValue;
  };

  const [imageDuration, setImageDuration] = useState<number>(() => getSavedValue('imageDuration', 3000));
  const [blackDuration, setBlackDuration] = useState<number>(() => getSavedValue('blackDuration', 100));
  const [qrLevel, setQrLevel] = useState<"L" | "M" | "Q" | "H">(() => getSavedValue('qrLevel', 'L'));
  const [qrSize, setQrSize] = useState<number>(() => getSavedValue('qrSize', 150));

  // 設定が変更されたらLocalStorageに保存
  useEffect(() => {
    localStorage.setItem('qr_config_imageDuration', JSON.stringify(imageDuration));
    localStorage.setItem('qr_config_blackDuration', JSON.stringify(blackDuration));
    localStorage.setItem('qr_config_qrLevel', JSON.stringify(qrLevel));
    localStorage.setItem('qr_config_qrSize', JSON.stringify(qrSize));
  }, [imageDuration, blackDuration, qrLevel, qrSize]);

  // 初期選択処理
  useEffect(() => {
    if (categories.length > 0 && !selectedListKey) setSelectedListKey(categories[0]);
  }, [categories, selectedListKey]);

  const currentCategoryData = dataSets[selectedListKey] || [];
  
  useEffect(() => {
    if (currentCategoryData.length > 0) {
      setCheckedItems(new Array(currentCategoryData.length).fill(true));
      setCurrentIndex(0);
      setIsActive(false);
      setShowImage(true);
    }
  }, [selectedListKey, currentCategoryData.length]);

  const activeDataList = currentCategoryData.filter((_, index) => checkedItems[index]);
  const currentRecord = activeDataList[currentIndex];

  // ==========================================
  // 3. 自動スワイプタイマー
  // ==========================================
  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (isActive && activeDataList.length > 0) {
      if (showImage) {
        timer = setTimeout(() => setShowImage(false), imageDuration);
      } else {
        timer = setTimeout(() => {
          if (currentIndex < activeDataList.length - 1) {
            setCurrentIndex(prev => prev + 1);
            setShowImage(true);
          } else {
            setIsActive(false);
            setShowImage(true);
          }
        }, blackDuration);
      }
    }
    return () => clearTimeout(timer);
  }, [isActive, showImage, currentIndex, activeDataList.length, imageDuration, blackDuration]);

  if (loading) {
    return (
      <div className="text-center py-5"><Spinner animation="border" /></div>
    );
  }

  if (loadError) {
    return (
      <Container className="pt-4">
        <Alert variant="danger">{loadError}</Alert>
      </Container>
    );
  }

  return (
    <>
      {isActive && !showImage && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', backgroundColor: '#000', zIndex: 9999 }} />
      )}

      <div style={{ backgroundColor: '#f0f2f5', minHeight: '100vh', paddingBottom: '50px' }}>
        <Container className="pt-4" style={{ maxWidth: '600px' }}>
          
          <div className="text-center mb-3">
            <h4 style={{ color: '#444', fontWeight: '800', margin: 0 }}>
              QR SWIPER <span style={{ color: '#3bc0bd', fontSize: '0.8em' }}>| {selectedListKey}</span>
            </h4>
          </div>

          <Card 
            className="shadow border-0 text-center mb-3" 
            style={{ borderRadius: '24px', backgroundColor: '#fff', minHeight: '280px', cursor: isActive || activeDataList.length === 0 ? 'default' : 'pointer', userSelect: 'none', WebkitTapHighlightColor: 'transparent' }}
            onClick={(e) => {
              if (isActive || activeDataList.length === 0) return;
              const rect = e.currentTarget.getBoundingClientRect();
              const clickX = e.clientX - rect.left;
              if (clickX > rect.width / 2) setCurrentIndex(prev => Math.min(activeDataList.length - 1, prev + 1));
              else setCurrentIndex(prev => Math.max(0, prev - 1));
              setShowImage(true);
            }}
          >
            <Card.Body className="p-4 d-flex flex-column align-items-center justify-content-center">
              {currentRecord ? (
                <>
                  <div style={{ width: `${qrSize}px`, height: `${qrSize}px`, display: 'flex', justifyContent: 'center', alignItems: 'center', transition: 'all 0.3s ease' }}>
                    <QRCodeSVG value={currentRecord.読み取りデータ || ''} size={qrSize} level={qrLevel} />
                  </div>
                  <div className="mt-3">
                    <Badge bg="dark" className="px-3 py-1 shadow-sm" style={{ fontSize: '0.85rem' }}>
                      {currentRecord.QRファイル名}
                    </Badge>
                  </div>
                  <div className="d-flex justify-content-between w-100 mt-4 px-4" style={{ opacity: 0.3, fontSize: '0.7rem', fontWeight: 'bold' }}>
                    <span>◀ 戻る</span>
                    <span>進む ▶</span>
                  </div>
                </>
              ) : (
                <div className="text-muted fw-bold">表示データがありません</div>
              )}
            </Card.Body>
          </Card>

          <div className="mb-4 px-1">
            <div className="d-flex justify-content-between align-items-center mb-1">
              <span className="small fw-bold text-muted">📊 PROGRESS</span>
              <span className="small fw-bold text-muted">{activeDataList.length > 0 ? `${currentIndex + 1} / ${activeDataList.length}` : '0 / 0'}</span>
            </div>
            <div className="d-flex shadow-sm" style={{ height: '10px', borderRadius: '5px', overflow: 'hidden', backgroundColor: '#e9ecef' }}>
              {activeDataList.map((_, idx) => (
                <div key={idx} style={{ flex: 1, backgroundColor: idx === currentIndex ? '#3bc0bd' : (idx < currentIndex ? '#888' : '#ddd'), borderRight: '1px solid rgba(255,255,255,0.3)', transition: 'background-color 0.2s' }} />
              ))}
            </div>
          </div>

          <Card className="shadow-sm border-0 mb-3" style={{ borderRadius: '16px', overflow: 'hidden' }}>
            <div style={{ height: '6px', backgroundColor: '#3bc0bd' }}></div>
            <Card.Body className="p-3">
              
              <div className="mb-3 p-2" style={{ backgroundColor: '#f8f9fa', borderRadius: '12px' }}>
                <Form.Label className="small fw-bold text-muted mb-1 text-uppercase">📁 カテゴリ選択</Form.Label>
                <Form.Select 
                  value={selectedListKey} 
                  onChange={(e) => setSelectedListKey(e.target.value)} 
                  className="border-0 shadow-sm fw-bold bg-white"
                  disabled={isActive}
                >
                  {categories.map(cat => (
                    <option key={cat} value={cat}>{cat} ({dataSets[cat].length}件)</option>
                  ))}
                </Form.Select>
              </div>

              <div className="d-flex gap-2 mb-3">
                <Button 
                  variant={isActive ? "danger" : "primary"} 
                  className="flex-fill fw-bold shadow-sm py-2"
                  style={{ borderRadius: '10px', fontSize: '1.05rem' }}
                  onClick={() => {
                    if (activeDataList.length === 0) return;
                    if (!isActive && currentIndex >= activeDataList.length - 1) setCurrentIndex(0);
                    setIsActive(!isActive);
                    setShowImage(true);
                  }}
                  disabled={activeDataList.length === 0}
                >
                  {isActive ? "■ 停止" : "▶ 自動スワイプ開始"}
                </Button>
              </div>

              <Accordion className="shadow-sm mb-2" style={{ borderRadius: '12px', overflow: 'hidden' }}>
                <Accordion.Item eventKey="settings" style={{ border: 'none', borderBottom: '1px solid #eee' }}>
                  <Accordion.Header>
                    <span style={{ fontSize: '0.85rem', fontWeight: 'bold', color: '#555' }}>⚙️ 詳細設定 (自動保存)</span>
                  </Accordion.Header>
                  <Accordion.Body className="p-3" style={{ backgroundColor: '#fafafa' }}>
                    <Row className="mb-3">
                      <Col xs={6}>
                        <Form.Label className="small fw-bold text-muted mb-1">QR表示 (ms)</Form.Label>
                        <Form.Control type="number" step="100" min="500" value={imageDuration} onChange={(e) => setImageDuration(Number(e.target.value))} disabled={isActive} size="sm" />
                      </Col>
                      <Col xs={6}>
                        <Form.Label className="small fw-bold text-muted mb-1">暗転 (ms)</Form.Label>
                        <Form.Control type="number" step="100" min="100" value={blackDuration} onChange={(e) => setBlackDuration(Number(e.target.value))} disabled={isActive} size="sm" />
                      </Col>
                    </Row>
                    <Row className="mb-1">
                      <Col xs={6}>
                        <Form.Label className="small fw-bold text-muted mb-1">誤り訂正</Form.Label>
                        <Form.Select value={qrLevel} onChange={(e) => setQrLevel(e.target.value as any)} disabled={isActive} size="sm">
                          <option value="L">L (7%)</option>
                          <option value="M">M (15%)</option>
                          <option value="Q">Q (25%)</option>
                          <option value="H">H (30%)</option>
                        </Form.Select>
                      </Col>
                      <Col xs={6}>
                        <Form.Label className="small fw-bold text-muted mb-1">QRサイズ</Form.Label>
                        <Form.Select value={qrSize} onChange={(e) => setQrSize(Number(e.target.value))} disabled={isActive} size="sm">
                          <option value={100}>100px</option>
                          <option value={125}>125px</option>
                          <option value={150}>150px</option>
                          <option value={175}>175px</option>
                          <option value={200}>200px</option>
                        </Form.Select>
                      </Col>
                    </Row>
                    <div className="text-end mt-2">
                       <small className="text-muted" style={{fontSize: '0.65rem'}}>※変更は即座にブラウザに保存されます</small>
                    </div>
                  </Accordion.Body>
                </Accordion.Item>

                <Accordion.Item eventKey="check" style={{ border: 'none' }}>
                  <Accordion.Header>
                    <span style={{ fontSize: '0.85rem', fontWeight: 'bold', color: '#555' }}>📋 項目管理 ({activeDataList.length}件)</span>
                  </Accordion.Header>
                  <Accordion.Body className="p-0" style={{ backgroundColor: '#fff' }}>
                    <div className="d-flex p-2 gap-2" style={{ backgroundColor: '#f8f9fa', borderBottom: '1px solid #ddd' }}>
                      <Button variant="outline-success" size="sm" className="flex-fill fw-bold" disabled={isActive} onClick={() => setCheckedItems(new Array(currentCategoryData.length).fill(true))}>✓ 全選択</Button>
                      <Button variant="outline-secondary" size="sm" className="flex-fill fw-bold" disabled={isActive} onClick={() => setCheckedItems(new Array(currentCategoryData.length).fill(false))}>全解除</Button>
                    </div>
                    <div style={{ maxHeight: '250px', overflowY: 'auto' }}>
                      <Table hover style={{ fontSize: '0.85rem', marginBottom: 0 }}>
                        <tbody>
                          {currentCategoryData.map((item, idx) => (
                            <tr key={idx}>
                              <td style={{ width: '40px' }} className="text-center align-middle">
                                <Form.Check type="checkbox" checked={checkedItems[idx] || false} onChange={() => {
                                  const next = [...checkedItems];
                                  next[idx] = !next[idx];
                                  setCheckedItems(next);
                                }} disabled={isActive} />
                              </td>
                              <td className="fw-bold align-middle" style={{ color: checkedItems[idx] ? '#000' : '#aaa' }}>
                                {item.QRファイル名}
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </Table>
                    </div>
                  </Accordion.Body>
                </Accordion.Item>
              </Accordion>

            </Card.Body>
          </Card>
        </Container>
      </div>
    </>
  );
};

export default QrRead;